import{_ as a,o as t,c as e,a5 as n}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"44. Working with stdin, stdout, and stderr","description":"The Little Book of C — 44. Working with stdin, stdout, and stderr","frontmatter":{"title":"44. Working with stdin, stdout, and stderr","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Input Output and Files"],"description":"The Little Book of C — 44. Working with stdin, stdout, and stderr","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":44,"sidebarWeight":44,"lang":"en-US","alternateEn":"/posts/c教程/en-US/05-Input Output and Files/044-Working with stdin, stdout, and stderr","alternateZh":"/posts/c教程/zh-CN/05-输入输出与文件/044-Working with stdin, stdout, and stderr"},"headers":[],"relativePath":"posts/c教程/en-US/05-Input Output and Files/044-Working with stdin, stdout, and stderr.md","filePath":"posts/c教程/en-US/05-Input Output and Files/044-Working with stdin, stdout, and stderr.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/05-Input Output and Files/044-Working with stdin, stdout, and stderr.md"};function o(p,s,d,r,l,c){return t(),e("div",null,[...s[0]||(s[0]=[n(`<p>[中文版本](/posts/c教程/zh-CN/05-输入输出与文件/044-Working with stdin, stdout, and stderr)</p><p>Every C program automatically starts with three open streams connected to your environment, the keyboard, the terminal screen, and the error console. They are the standard I/O streams that make your programs flexible and scriptable.</p><p>Understanding these three streams is crucial for writing tools that can interact with files, pipes, and other programs, the essence of Unix-style design.</p><h4 id="the-three-standard-streams" tabindex="-1">The Three Standard Streams <a class="header-anchor" href="#the-three-standard-streams" aria-label="Permalink to &quot;The Three Standard Streams&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Stream</th><th>Purpose</th><th>Typical Device</th><th>Example Use</th></tr></thead><tbody><tr><td><code>stdin</code></td><td>Standard Input</td><td>Keyboard (or file via<code>&lt;</code>)</td><td><code>scanf</code>,<code>fgets</code></td></tr><tr><td><code>stdout</code></td><td>Standard Output</td><td>Screen (or file via<code>&gt;</code>)</td><td><code>printf</code>,<code>puts</code>,<code>fprintf(stdout, …)</code></td></tr><tr><td><code>stderr</code></td><td>Standard Error</td><td>Screen (separate from stdout)</td><td><code>fprintf(stderr, …)</code></td></tr></tbody></table><p>These are all of type<code>FILE *</code>. You can treat them like normal file pointers, reading, writing, or redirecting them.</p><h4 id="basic-example" tabindex="-1">Basic Example <a class="header-anchor" href="#basic-example" aria-label="Permalink to &quot;Basic Example&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char name[50];</span></span>
<span class="line"><span>    printf(&quot;Enter your name: &quot;);</span></span>
<span class="line"><span>    fgets(name, sizeof(name), stdin);</span></span>
<span class="line"><span>    fprintf(stdout, &quot;Hello, %s&quot;, name);</span></span>
<span class="line"><span>    fprintf(stderr, &quot;Note: This is an example error message.\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Enter your name: Alice</span></span>
<span class="line"><span>Hello, Alice</span></span>
<span class="line"><span>Note: This is an example error message.</span></span></code></pre></div><h4 id="redirection-in-the-shell" tabindex="-1">Redirection in the Shell <a class="header-anchor" href="#redirection-in-the-shell" aria-label="Permalink to &quot;Redirection in the Shell&quot;">​</a></h4><p>You can redirect each stream separately:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program &lt; input.txt &gt; output.txt 2&gt; errors.log</span></span></code></pre></div><ul><li><code>&lt;</code> replaces<code>stdin</code>(read input from file)</li><li><code>&gt;</code> replaces<code>stdout</code>(write normal output to file)</li><li><code>2&gt;</code> replaces<code>stderr</code>(write errors to file)</li></ul><p>You can also combine them:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program &gt; all_output.txt 2&gt;&amp;1</span></span></code></pre></div><p>This merges both output and error streams into one file.</p><h4 id="reading-from-stdin" tabindex="-1">Reading from stdin <a class="header-anchor" href="#reading-from-stdin" aria-label="Permalink to &quot;Reading from stdin&quot;">​</a></h4><p>You can build programs that process input dynamically, one line at a time:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char line[100];</span></span>
<span class="line"><span>    printf(&quot;Enter text (Ctrl+D to stop):\\n&quot;);</span></span>
<span class="line"><span>    while (fgets(line, sizeof(line), stdin))</span></span>
<span class="line"><span>        printf(&quot;You said: %s&quot;, line);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Now your program behaves like a Unix filter, it can read from a file, a pipe, or a keyboard input interchangeably.</p><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo &quot;hello&quot; | ./program</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You said: hello</span></span></code></pre></div><h4 id="writing-to-stdout-and-stderr" tabindex="-1">Writing to stdout and stderr <a class="header-anchor" href="#writing-to-stdout-and-stderr" aria-label="Permalink to &quot;Writing to stdout and stderr&quot;">​</a></h4><p><code>stdout</code> is for normal program output, while<code>stderr</code> is for error messages or logs.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    fprintf(stdout, &quot;Everything is fine.\\n&quot;);</span></span>
<span class="line"><span>    fprintf(stderr, &quot;Warning: something might be wrong.\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>You can suppress normal output but keep errors:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program &gt; /dev/null</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Warning: something might be wrong.</span></span></code></pre></div><h4 id="tiny-code-word-counter-using-stdin-stdout" tabindex="-1">Tiny Code: Word Counter Using stdin/stdout <a class="header-anchor" href="#tiny-code-word-counter-using-stdin-stdout" aria-label="Permalink to &quot;Tiny Code: Word Counter Using stdin/stdout&quot;">​</a></h4><p>This small program mimics a simplified version of the Unix<code>wc</code> command.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;ctype.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int ch, words = 0, in_word = 0;</span></span>
<span class="line"><span>    while ((ch = getchar()) != EOF) {</span></span>
<span class="line"><span>        if (isspace(ch))</span></span>
<span class="line"><span>            in_word = 0;</span></span>
<span class="line"><span>        else if (!in_word) {</span></span>
<span class="line"><span>            in_word = 1;</span></span>
<span class="line"><span>            words++;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    printf(&quot;Word count: %d\\n&quot;, words);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Try:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo &quot;C is small but powerful&quot; | ./wordcount</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Word count: 4</span></span></code></pre></div><h4 id="mixing-stdout-and-stderr" tabindex="-1">Mixing stdout and stderr <a class="header-anchor" href="#mixing-stdout-and-stderr" aria-label="Permalink to &quot;Mixing stdout and stderr&quot;">​</a></h4><p>Sometimes you need to log progress to<code>stderr</code> while outputting results to<code>stdout</code>. That way, logs don’t pollute the actual data.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    for (int i = 0; i &lt; 3; i++) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Processing item %d...\\n&quot;, i + 1);</span></span>
<span class="line"><span>        fprintf(stdout, &quot;Item %d processed\\n&quot;, i + 1);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Redirect logs separately:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program &gt; result.txt 2&gt; log.txt</span></span></code></pre></div><h4 id="flushing-buffers" tabindex="-1">Flushing Buffers <a class="header-anchor" href="#flushing-buffers" aria-label="Permalink to &quot;Flushing Buffers&quot;">​</a></h4><p>Output streams are buffered, data isn’t written until the buffer is full or flushed. To ensure output appears immediately:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fflush(stdout);  // flush output buffer</span></span></code></pre></div><p>This is useful for interactive programs.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>These three streams give your program flexibility:</p><ul><li>Work interactively (keyboard/screen)</li><li>Work in batch (file input/output)</li><li>Chain with other tools using pipes</li></ul><p>They are the foundation of the Unix philosophy: small programs that do one thing well and can be composed together.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a program that reads from stdin and prints only lines containing a given keyword.</li><li>Print errors to stderr if no keyword is provided.</li><li>Redirect input and output from files using<code>&lt;</code> and<code>&gt;</code>.</li><li>Add progress messages to stderr and redirect them to a separate log.</li><li>Combine everything into a small “filter” tool that processes text from pipelines.</li></ol><p>With<code>stdin</code>,<code>stdout</code>, and<code>stderr</code>, your C programs become tools that fit seamlessly into real workflows, able to interact with files, other programs, and users alike. Next, you’ll explore buffered I/O, understanding how the C library optimizes performance through read and write buffers using<code>fgets</code>,<code>fputs</code>, and more.</p>`,55)])])}const g=a(i,[["render",o]]);export{h as __pageData,g as default};
